<div class="two-col"><section class="card"><h2>Add an entry</h2><p class="muted">A valuation is the total asset value on that date. Later deposits and withdrawals adjust that value.</p><form class="stack" method="post" action="/investments/<?= e($a['id']) ?>/txn"><?= csrf_field() ?><label>Entry type<select name="type"><option value="deposit">Deposit — money in</option><option value="withdraw">Withdrawal — money out</option><option value="valuation">Valuation — total current value</option></select></label><label>Date<input type="date" name="date" value="<?= e(date('Y-m-d')) ?>" required></label><label>Amount (Rs.)<input type="number" min="0" max="9999999999.99" step="0.01" name="amount" required></label><label>Cash account (optional)<select name="account_id"><option value="">External capital / no cash transfer</option><?php foreach ($accounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><p class="footnote">For deposits, subtract from this account. For withdrawals, return money to it. Leave empty for valuations or external capital.</p><label>Note<input name="note" maxlength="1000"></label><button>Save entry</button></form></section><section class="card"><h2>Monthly business numbers</h2><form class="stack" method="post" action="/investments/<?= e($a['id']) ?>/metric"><?= csrf_field() ?><label>Month<input type="month" name="month" value="<?= e(date('Y-m')) ?>" required></label><label>Revenue (Rs.)<input type="number" min="0" max="9999999999.99" step="0.01" name="revenue" required></label><label>Cost (Rs.)<input type="number" min="0" max="9999999999.99" step="0.01" name="cost" required></label><button>Save month</button></form><p class="footnote">Saving the same month updates its existing figures.</p><h3>Asset status</h3><form class="inline" method="post" action="/investments/<?= e($a['id']) ?>/status"><?= csrf_field() ?><label class="sr-only" for="asset-status">Status</label><select id="asset-status" name="status"><option value="active" <?= $a['status']==='active' ? 'selected' : '' ?>>Active</option><option value="closed" <?= $a['status']==='closed' ? 'selected' : '' ?>>Closed</option></select><button class="secondary">Update status</button></form><p class="footnote">Closed assets stay in your history and are excluded from active net worth.</p></section></div>
<section class="card"><h2>Transaction history</h2><?php if (!$txs): ?><p class="muted">No entries yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Date / type</th><th>Amount</th><th>Note</th><th>Action</th></tr></thead><tbody><?php foreach ($txs as $t): ?><tr><td><?= e($t['date']) ?><small><?= e(ucfirst($t['type'])) ?><?= $t['date']>date('Y-m-d') ? ' · Future entry' : '' ?></small></td><td><?= money($t['amount']) ?></td><td><?= e($t['note']) ?><?= $t['income_id'] ? ' · Income #'.e($t['income_id']) : '' ?></td><td><?php if (!$t['income_id']): ?><form method="post" action="/investments/<?= e($a['id']) ?>/txn/<?= e($t['id']) ?>/delete" data-confirm="Delete this asset entry?"><?= csrf_field() ?><button class="delete">Delete</button></form><?php else: ?><small>Linked to income</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
